sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
.servicos-widget {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: flex-start; /* Alinha à esquerda */
  max-width: 80%;
  margin: 25px auto 2rem 0; /* margem esquerda zero para colar na esquerda */
  position: static;
  text-align: left; /* texto alinhado à esquerda */
 		margin-top: 0px;
    margin-right: 0px;
}


.servicos-text {
  font-size: 3.4rem;
  color: #293273;
  padding: 10px;
}
.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Responsivo */
@media (max-width: 900px) {
  .servicos-widget {
    max-width: 90%;
  }
}
